"""Exact rational verification of the collapse identity [x,b) cap (a,x] = {x}."""
from fractions import Fraction
from typing import Sequence, Set


def half_open_right(x: Fraction, b: Fraction, grid: Sequence[Fraction]) -> Set[Fraction]:
    return {p for p in grid if x <= p < b}


def half_open_left(a: Fraction, x: Fraction, grid: Sequence[Fraction]) -> Set[Fraction]:
    return {p for p in grid if a < p <= x}


def verify_singleton_collapse(a: Fraction, x: Fraction, b: Fraction,
                              grid: Sequence[Fraction]) -> bool:
    assert a < x < b
    return half_open_left(a, x, grid) & half_open_right(x, b, grid) == {x}


if __name__ == "__main__":
    step = Fraction(1, 12)
    grid = [Fraction(-24) * step + k * step for k in range(97)]
    for (a, x, b) in [(Fraction(-1), Fraction(0), Fraction(1)),
                      (Fraction(-1, 2), Fraction(1, 3), Fraction(3, 2)),
                      (Fraction(0), Fraction(1, 2), Fraction(2))]:
        print(a, x, b, "->", verify_singleton_collapse(a, x, b, grid))

"""Consensus (supremum) and possibility (infimum) of finite topologies, and the
sandwich  possibility <= observer <= consensus."""
from itertools import combinations
from typing import FrozenSet, Iterable, Sequence, Set

Point = int
OpenSet = FrozenSet[Point]
Topology = FrozenSet[OpenSet]


def generate_topology(ground: FrozenSet[Point], subbasis: Iterable[OpenSet]) -> Topology:
    basis: Set[OpenSet] = {frozenset(), ground}
    for s in subbasis:
        basis.add(frozenset(s) & ground)
    changed = True
    while changed:
        changed = False
        for u in list(basis):
            for v in list(basis):
                w = u & v
                if w not in basis:
                    basis.add(w); changed = True
    opens: Set[OpenSet] = {frozenset(), ground}
    for r in range(1, len(basis) + 1):
        for combo in combinations(basis, r):
            opens.add(frozenset().union(*combo))
    return frozenset(opens)


def consensus(ts: Sequence[Topology]) -> Topology:
    result: Set[OpenSet] = set(ts[0])
    for t in ts[1:]:
        result &= set(t)
    return frozenset(result)


def possibility(ground: FrozenSet[Point], ts: Sequence[Topology]) -> Topology:
    union: Set[OpenSet] = set()
    for t in ts:
        union |= set(t)
    return generate_topology(ground, union)


if __name__ == "__main__":
    ground = frozenset({0, 1, 2})
    A = generate_topology(ground, [frozenset({0}), frozenset({0, 1})])
    B = generate_topology(ground, [frozenset({2}), frozenset({1, 2})])
    con, pos = consensus([A, B]), possibility(ground, [A, B])
    print("consensus:", sorted(map(sorted, con)))
    print("possibility:", sorted(map(sorted, pos)))
    print("possibility <= A:", set(A) <= set(pos))
    print("A <= consensus:", set(con) <= set(A))

"""Half-open twin observers on a finite ordered sample: pooling isolates every point."""
from fractions import Fraction
from itertools import combinations
from typing import FrozenSet, Iterable, List, Sequence, Set

Point = int
OpenSet = FrozenSet[Point]
Topology = FrozenSet[OpenSet]


def generate_topology(ground: FrozenSet[Point], subbasis: Iterable[OpenSet]) -> Topology:
    basis: Set[OpenSet] = {frozenset(), ground}
    for s in subbasis:
        basis.add(frozenset(s) & ground)
    changed = True
    while changed:
        changed = False
        for u in list(basis):
            for v in list(basis):
                w = u & v
                if w not in basis:
                    basis.add(w); changed = True
    opens: Set[OpenSet] = {frozenset(), ground}
    for r in range(1, len(basis) + 1):
        for combo in combinations(basis, r):
            opens.add(frozenset().union(*combo))
    return frozenset(opens)


def right_looking(sample: Sequence[Fraction]) -> Topology:
    g = frozenset(range(len(sample)))
    sub = [frozenset(j for j in range(len(sample)) if sample[j] >= sample[i])
           for i in range(len(sample))]
    return generate_topology(g, sub)


def left_looking(sample: Sequence[Fraction]) -> Topology:
    g = frozenset(range(len(sample)))
    sub = [frozenset(j for j in range(len(sample)) if sample[j] <= sample[i])
           for i in range(len(sample))]
    return generate_topology(g, sub)


if __name__ == "__main__":
    sample: List[Fraction] = [Fraction(k, 2) for k in range(-2, 3)]
    g = frozenset(range(len(sample)))
    L, R = left_looking(sample), right_looking(sample)
    union: Set[OpenSet] = set(L) | set(R)
    pos = generate_topology(g, union)
    for i, v in enumerate(sample):
        print(f"{{{v}}} open in possibility:", frozenset({i}) in pos)
    print("possibility is discrete:", len(pos) == 2 ** len(sample))

