function GENERATE_TOPOLOGY(ground, subbasis):
    basis <- {empty, ground} union { s cap ground : s in subbasis }
    repeat until no change:
        for all u, v in basis:
            add (u cap v) to basis
    opens <- {empty, ground}
    for each nonempty subset C of basis:
        add (union of C) to opens
    return opens

